-- Where each figure sits in BOT's own workbook.
--
-- A filed return is an .xlsx built by populating BOT's template, not a
-- spreadsheet of this system's own design. Which cell holds which figure is
-- therefore a fact about *their* file, and it is seeded here rather than
-- computed in code: when BOT inserts a line in a revision, the fix is a
-- migration, and the exporter is untouched.
--
-- The map is generated by `docs/reference/extract-bot-cells.py`, which reads
-- the template and resolves every taxonomy code against the seeds in migration
-- 0004. A name it cannot match fails at generation time.
--
-- One rule runs through the whole thing: **this system writes only where BOT's
-- template has no formula.** A cell BOT computes is BOT's answer, and writing
-- over it would replace their arithmetic with ours — the arithmetic their EDI
-- validator checks against. So computed cells simply have no row here and the
-- exporter has nowhere to put a figure for them.
--
-- The single exception is stated where it arises, below.

-- ---------------------------------------------------------------------------
-- The sheets
-- ---------------------------------------------------------------------------

CREATE TABLE reference.form_sheets (
  form_code       text     PRIMARY KEY,
  -- BOT's own tab name. Note MSP2-01's tab is spelled `MSP2_01` with an
  -- underscore and the other nine use a hyphen; that inconsistency is theirs.
  sheet_name      text     NOT NULL UNIQUE,
  -- A line's row is its Sno plus this. Uniform at 13 across all ten sheets
  -- today, held as a column so a revision that shifts one sheet's header does
  -- not shift the other nine.
  sno_row_offset  smallint NOT NULL CHECK (sno_row_offset > 0),
  -- The column carrying the institution's name (row 2), its MSP code (row 4)
  -- and the quarter-end date (row 6).
  --
  -- This is the exception to "never write where BOT has a formula". On nine of
  -- the ten sheets those three cells are `=[1]MSP2_01!C2` and the like: `[1]`
  -- is an external workbook named `minne.xlsm` that BOT does not ship with the
  -- template, and whose cached values read "TESTING MSP" / "M001" /
  -- 31-12-2021. Left alone, every form but the balance sheet would carry
  -- another institution's name. They are overwritten with literal values.
  identity_column text     NOT NULL CHECK (identity_column ~ '^[A-Z]{1,2}$')
);

COMMENT ON TABLE reference.form_sheets IS
  'One row per BOT MSP2 form: its sheet in the template, and how Sno maps to a row.';

-- ---------------------------------------------------------------------------
-- The columns
-- ---------------------------------------------------------------------------

-- Keyed by the name this system's own wire shapes use, so the exporter reads as
-- a translation between two vocabularies rather than a table of bare letters.
CREATE TABLE reference.form_columns (
  form_code     text NOT NULL REFERENCES reference.form_sheets (form_code),
  column_key    text NOT NULL,
  column_letter text NOT NULL CHECK (column_letter ~ '^[A-Z]{1,2}$'),
  PRIMARY KEY (form_code, column_key),
  -- Two figures in one cell would mean one of them is lost, and which one
  -- would depend on write order.
  UNIQUE (form_code, column_letter)
);

-- ---------------------------------------------------------------------------
-- The rows
-- ---------------------------------------------------------------------------

-- What a row is *about* differs by form: a numbered line on the balance sheet,
-- a sector on MSP2-03, a district on MSP2-10. Each is a real foreign key rather
-- than a free-text discriminator, so a map row that names something the
-- reference data does not contain cannot be inserted at all.
CREATE TABLE reference.form_rows (
  form_code      text     NOT NULL REFERENCES reference.form_sheets (form_code),
  row_number     smallint NOT NULL CHECK (row_number >= 14),
  sno            smallint,
  sector_code    text     REFERENCES reference.sectors (code),
  loan_type_code text     REFERENCES reference.loan_types (code),
  district_code  text     REFERENCES reference.districts (code),
  PRIMARY KEY (form_code, row_number),
  -- A row addresses exactly one thing. Two would make the exporter's lookup
  -- ambiguous; none would make the row unreachable.
  CONSTRAINT form_rows_addresses_one_thing CHECK (
    (sno IS NOT NULL)::int
      + (sector_code IS NOT NULL)::int
      + (loan_type_code IS NOT NULL)::int
      + (district_code IS NOT NULL)::int = 1
  ),
  -- A numbered line must be a line BOT actually has. `reference.form_lines` is
  -- seeded for the three forms addressed that way.
  CONSTRAINT form_rows_line_exists
    FOREIGN KEY (form_code, sno) REFERENCES reference.form_lines (form_code, sno)
);

-- The same subject cannot appear on two rows of one form, in either direction.
CREATE UNIQUE INDEX form_rows_sector_idx
  ON reference.form_rows (form_code, sector_code) WHERE sector_code IS NOT NULL;
CREATE UNIQUE INDEX form_rows_loan_type_idx
  ON reference.form_rows (form_code, loan_type_code) WHERE loan_type_code IS NOT NULL;
CREATE UNIQUE INDEX form_rows_district_idx
  ON reference.form_rows (form_code, district_code) WHERE district_code IS NOT NULL;

-- ---------------------------------------------------------------------------
-- The free sections
-- ---------------------------------------------------------------------------

-- MSP2-07 and MSP2-08 do not name their counterparties in advance: the rows are
-- blank, and the institution picks a bank from a dropdown beside the amount. So
-- those forms are addressed as ranges filled in order, and the number of rows
-- BOT allows is a real limit — an institution banking with twenty-nine banks
-- has one it cannot report. The exporter refuses rather than dropping a
-- holding, because a return that is quietly short is worse than one that is
-- late.
CREATE TABLE reference.form_sections (
  form_code   text     NOT NULL REFERENCES reference.form_sheets (form_code),
  section_key text     NOT NULL,
  first_row   smallint NOT NULL CHECK (first_row >= 14),
  last_row    smallint NOT NULL,
  PRIMARY KEY (form_code, section_key),
  CONSTRAINT form_sections_is_a_range CHECK (last_row >= first_row)
);

-- ---------------------------------------------------------------------------
-- The map
-- ---------------------------------------------------------------------------







-- 91 numbered lines, 44 sector rows, 14 loan-type rows, 193 district rows.

-- Sno34 has a writable cell and no formula, and is still not a cell this system
-- may fill. Migration 0015 established why: "8. LIABILITIES" is a section
-- heading, and Sno50 (Total Liabilities) sums Sno35, 46, 47, 48 and 49 without
-- it. A figure written there is reported nowhere. Entry is already refused; the
-- exporter is given no cell to write either, so the two agree.
DELETE FROM reference.form_rows WHERE form_code = 'MSP2-01' AND sno = 34;

-- ---------------------------------------------------------------------------
-- Access
-- ---------------------------------------------------------------------------

-- Reference data, like the rest of the schema: readable by the application
-- role, written only by a migration.
GRANT SELECT ON reference.form_sheets, reference.form_columns,
                reference.form_rows, reference.form_sections TO mfi_app;
